academic_sqlite.schema_text:
student(s_id INTEGER PRIMARY KEY, s_name TEXT NOT NULL, dept_name TEXT);
takes(s_id INTEGER, course_id TEXT, semester TEXT, grade TEXT);
course(course_id TEXT PRIMARY KEY, title TEXT, dept_name TEXT, credits INTEGER);
instructor(i_id INTEGER PRIMARY KEY, i_name TEXT, dept_name TEXT, salary INTEGER, bonus INTEGER);
department(dept_name TEXT PRIMARY KEY, building TEXT, budget INTEGER)
